        emoji: '🔥',
        body: `▼ゼロから：ストーブに手をかざすと、触れていないのに熱いですね。これは赤外線という目に見えない光が飛んできているからです。じつは温度をもつ物体はすべて、その温度に応じた電磁波をつねに出しています。これを熱放射といいます。太陽も、地球も、雲も、あなたの体も放射を出しています。気象学のエネルギーの話は、すべてこの熱放射から始まります。試験ではこの量を数式で計算させられるので、まず黒体という理想の物体を理解しましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 黒体とはなにか
━━━━━━━━━━━━━━━━━━━━━━
・黒体とは、入射した放射をすべての波長で完全に吸収し、その温度で出しうる最大の放射を出す理想的な物体
・黒い色をしているからではなく、反射も透過もしないから黒体と呼ぶ
・実在はしないが、太陽の表面・地表面・水面・厚い雲の頂は黒体にかなり近い
・キルヒホッフの法則★：ある波長をよく吸収する物体は、同じ波長をよく放射する
→ 吸収率と射出率は、同じ波長・同じ温度で等しい
・現実の物体は射出率εを掛けて扱う。εは0から1の値をとる

━━━━━━━━━━━━━━━━━━━━━━
🔑 ステファン・ボルツマンの法則
━━━━━━━━━━━━━━━━━━━━━━
黒体が単位面積・単位時間あたりに全波長で出す放射エネルギーの総量Eは、絶対温度Tの4乗に比例します。

・式：E ＝ σ × T の4乗
・σはステファン・ボルツマン定数 ＝ 5.67×10のマイナス8乗 W/(m2・K4)
・Tは必ず絶対温度K★。セ氏温度を代入してはいけない
・黒体でない物体：E ＝ ε × σ × T の4乗

○4乗であることが最重要。温度がわずかに上がるだけで放射量は大きく増える
○この非線形性が、地球の気温を安定させる負のフィードバックの正体でもある

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例1：地表面が出す放射量
━━━━━━━━━━━━━━━━━━━━━━
地表面の温度が288K（約15度）のときの放射量を求めます。

式：E ＝ σ × T の4乗
代入：E ＝ 5.67×10のマイナス8乗 × 288の4乗
途中：288の4乗 ＝ 6.88×10の9乗
答え：E ≒ 390 W/m2

○地球の地表面はおよそ390 W/m2の赤外放射を上向きに出している
○これは太陽から地表に届く量よりずっと大きい。差を埋めているのが大気からの下向き赤外放射である

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例2：温度が2倍になったら
━━━━━━━━━━━━━━━━━━━━━━
式：比 ＝ (2T)の4乗 ÷ Tの4乗
途中：2の4乗 ＝ 16
答え：16倍★

・温度が1パーセント上がると放射量は約4パーセント増える（4乗のため）
・温度が10パーセント上がると放射量は約1.46倍になる

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例3：射出率が0.95の雪面
━━━━━━━━━━━━━━━━━━━━━━
式：E ＝ ε × σ × T の4乗
代入：E ＝ 0.95 × 5.67×10のマイナス8乗 × 263の4乗
途中：263の4乗 ＝ 4.79×10の9乗、σを掛けて272 W/m2
答え：E ≒ 258 W/m2

雪面は可視光では白く反射率が高いのに、赤外域では射出率0.95以上のほぼ黒体です。ここが典型的なひっかけになります★

【図解】温度と黒体放射量の対応
　温度｜σかけるTの4乗｜代表するもの｜
　255K｜約240 W/m2｜地球の放射平衡温度
　288K｜約390 W/m2｜地球の地表面の平均
　5800K｜約6.4かける10の7乗 W/m2｜太陽の表面
　⇒ 温度が20倍で放射量は約16万倍。4乗の効きめは絶大
　⚠「放射量は温度に比例する」は誤り。4乗に比例する

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「セ氏温度をそのまま代入してよい」→ 必ず絶対温度Kに直す。15度なら288K
・×「白く見える雪は赤外線もよく反射するので射出率が小さい」→ 誤り。可視と赤外を混同させる定番
・×「黒体とは真っ黒に見える物体のことである」→ 誤り。吸収率が1の理想物体という意味
・○「キルヒホッフの法則より、二酸化炭素は15マイクロメートル帯を強く吸収するので同じ帯を強く放射する」
・過去問では、実際の自然物の射出率が示され、それを用いた放射量を計算させる出題も出ています。水面はおよそ0.96、草地はおよそ0.95、乾いた砂はおよそ0.90、新雪はおよそ0.99で、いずれも1に近い値です。したがって地表面を黒体とみなす近似は、赤外域ではかなり良い近似になります。一方で可視域の反射率、すなわちアルベドは新雪で0.8を超え、水面では太陽高度が高いとき0.05程度と、まったく別の値になります。射出率とアルベドを混同しないことが得点の分かれ目です
・過去問では、地表面温度が数度変わったときの放射量の変化量を計算させる出題が定番です。4乗の微分から、温度の変化率に対して放射量の変化率は4倍になると覚えると速く解けます
・出題形式としては、射出率0.9の物体が温度300Kで出す放射量に最も近いものを選べ、という数値選択が多く見られます

★ここだけ暗記
・E ＝ εσTの4乗、σ ＝ 5.67×10のマイナス8乗
・288Kで約390 W/m2、255Kで約240 W/m2はそのまま覚える
・キルヒホッフの法則＝よく吸収する波長はよく放射する
・温度は絶対温度、射出率は赤外域ではほとんどの自然物で0.9以上`,
