・積雪：雪は熱伝導率が小さく、地中からの熱補給を遮断する。さらに射出率が高い
・盆地地形：冷たい重い空気が斜面を滑り落ちて底にたまる。これを冷気湖という★
・地面が乾いている：湿った土は熱容量が大きく冷えにくい

