・2つの気圧面の高度を引き算するだけで、その層の平均気温がわかる
・気温の観測点が少なくても、高度場から気温場が推定できる
・数値予報モデルでも、高度と気温は静水圧平衡で強く結びついている
・厚さ5400メートルの線は、日本付近で雪と雨を分ける目安としてよく使われる★

○1000hPaと500hPaの層厚は、対流圏下半分の平均的な暖かさを表す
○850hPaと700hPaの層厚は、下層の暖気移流の判断に使う

━━━━━━━━━━━━━━━━━━━━━━
