        emoji: '🌫️',
        body: `▼ゼロから：空気にどれだけ水蒸気が入っているかを表す方法は、じつは何通りもあります。重さで表すのか、圧力で表すのか、割合で表すのか。どれも同じ状態を別の角度から見ているだけですが、それぞれ得意な場面が違います。試験ではこれらの換算が繰り返し問われるので、定義と関係式をひととおり押さえましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 6つの表し方
━━━━━━━━━━━━━━━━━━━━━━
・水蒸気圧e：空気中の水蒸気が受け持つ分圧。単位はhPa
・飽和水蒸気圧es：その温度で入りうる最大の水蒸気圧。温度だけで決まる★
・混合比w：水蒸気の質量 ÷ 乾燥空気の質量。単位はg/kg
・比湿q：水蒸気の質量 ÷ 湿潤空気全体の質量。単位はg/kg
・相対湿度RH：e ÷ es をパーセントで表したもの
・絶対湿度：単位体積あたりの水蒸気の質量。単位はg/m3

○混合比と比湿はほぼ同じ値になる（差は2パーセント以内）★
○水蒸気圧と混合比と比湿は、空気塊が上下しても水蒸気の出入りがなければ保存される★
○相対湿度と絶対湿度は保存されない

━━━━━━━━━━━━━━━━━━━━━━
🔑 関係式
━━━━━━━━━━━━━━━━━━━━━━
・混合比：w ＝ 0.622 × e ÷ (p − e)
・簡略式：w ≒ 0.622 × e ÷ p（eがpに比べて小さいとき）★
・比湿：q ＝ 0.622 × e ÷ (p − 0.378 × e) ≒ w ÷ (1 ＋ w)
・相対湿度：RH ＝ (e ÷ es) × 100 ≒ (w ÷ ws) × 100

・0.622は水と空気の分子量比 18 ÷ 28.96 から来る★

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例1：混合比を求める
━━━━━━━━━━━━━━━━━━━━━━
気圧1000hPa、水蒸気圧20hPaのときの混合比を求めます。

式：w ＝ 0.622 × e ÷ (p − e)
代入：w ＝ 0.622 × 20 ÷ (1000 − 20)
途中：分子 ＝ 12.44、分母 ＝ 980
答え：w ＝ 0.0127 kg/kg ＝ 12.7 g/kg★

・簡略式なら 0.622 × 20 ÷ 1000 ＝ 0.01244 ＝ 12.4 g/kg
・誤差は約2パーセントで、実用上は十分

━━━━━━━━━━━━━━━━━━━━━━
🔑 計算例2：相対湿度を求める
━━━━━━━━━━━━━━━━━━━━━━
気温20度のときの飽和水蒸気圧を23.4hPaとし、実際の水蒸気圧が14hPaだったとします。

式：RH ＝ (e ÷ es) × 100
代入：RH ＝ (14 ÷ 23.4) × 100
答え：RH ≒ 60パーセント

・この空気を10度まで冷やすと、飽和水蒸気圧は12.3hPaになる
・14hPa は 12.3hPa を超えるので飽和し、余分な1.7hPa分が凝結する★

【図解】水蒸気量の表し方の使い分け
　量｜単位｜上下運動で保存されるか｜
　水蒸気圧｜hPa｜保存される（気圧比例で変化）
　混合比｜g/kg｜保存される★
　比湿｜g/kg｜保存される★
　相対湿度｜パーセント｜保存されない★
　⇒ 保存される量で空気塊を追い、相対湿度は状態の指標として使う
　⚠「相対湿度が同じなら水蒸気量も同じ」は誤り。気温が違えば全く違う

━━━━━━━━━━━━━━━━━━━━━━
🔑 相対湿度が変わりやすい理由
━━━━━━━━━━━━━━━━━━━━━━
・相対湿度は分母の飽和水蒸気圧が気温で激しく変わる
・気温が10度上がると飽和水蒸気圧はおよそ2倍になる★
→ 水蒸気量が同じでも、気温が10度上がれば相対湿度は約半分になる
→ 冬に暖房をかけると室内がからからになるのはこのため

・代入例：外気0度で相対湿度80パーセント（e ＝ 4.9hPa）の空気を20度まで暖める
・20度の飽和水蒸気圧は23.4hPa
・答え：RH ＝ (4.9 ÷ 23.4) × 100 ≒ 21パーセント

━━━━━━━━━━━━━━━━━━━━━━
🔑 絶対湿度と可降水量
━━━━━━━━━━━━━━━━━━━━━━
・絶対湿度 ＝ 水蒸気の密度 ＝ e ÷ (Rv × T)
・代入例：e ＝ 20hPa ＝ 2000Pa、T ＝ 293Kのとき
・計算：2000 ÷ (461 × 293) ＝ 0.0148 kg/m3 ＝ 14.8 g/m3
・可降水量は、この絶対湿度を鉛直方向に積分したもの

○絶対湿度は体積を基準にするので、空気塊が膨張すると減ってしまう
○そのため空気塊の追跡には向かず、混合比や比湿が使われる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「相対湿度は空気塊が上昇しても変わらない」→ 気温低下で飽和水蒸気圧が下がり、上がっていく
・×「混合比は湿潤空気全体の質量で割る」→ 乾燥空気の質量で割る。全体で割るのは比湿
・×「絶対湿度は空気塊の上下で保存される」→ 保存されない
・○「係数0.622は水と乾燥空気の分子量比である」
・過去問では、水蒸気圧と気圧から混合比を計算させる出題、気温変化にともなう相対湿度の変化を問う出題が頻出です

★ここだけ暗記
・w ＝ 0.622 かける e 割る (p 引く e)
・混合比と比湿はほぼ同じ、どちらも保存される
・相対湿度は保存されない
・気温10度上昇で飽和水蒸気圧は約2倍`,
