○状態曲線が右へ大きく傾く（気温が高さとともにあまり下がらない）ほど安定
○状態曲線が左へ急に傾く（気温が急に下がる）ほど不安定
○状態曲線が右へ折れ返る部分は逆転層

━━━━━━━━━━━━━━━━━━━━━━
