十種雲形のほかに、成因による分け方も重要です。

・対流雲：局所的な強い上昇流でできる。積雲、積乱雲★
・層状雲：広い範囲の弱い上昇流でできる。層雲、高層雲、乱層雲、巻層雲★
・波状雲：安定層の中を伝わる大気の波でできる。巻積雲、高積雲、層積雲
・地形性の雲：山にぶつかった気流でできる。レンズ雲、笠雲、旗雲

○対流雲は激しい雨を短時間に、層状雲は弱い雨を長時間降らせる
○同じ降水量でも、対流性か層状性かで災害の形が変わる

