━━━━━━━━━━━━━━━━━━━━━━
・曲率半径rが大きい（ほぼ直線）ほど、遠心力が小さくなり地衡風に近づく
・rが小さい（急な曲がり）ほど、地衡風とのずれが大きい
・気圧の谷（トラフ）の底では低気圧性の曲率が最大★
・気圧の尾根（リッジ）の頂では高気圧性の曲率が最大★

