━━━━━━━━━━━━━━━━━━━━━━
・大気追跡風：連続画像で雲や水蒸気の模様を追跡して風を求める★
・海面水温：赤外の窓領域から推定
・可降水量：水蒸気チャンネルとマイクロ波から推定
・降水強度：マイクロ波放射計と赤外の組み合わせ
・雲頂高度と光学的厚さ：複数バンドの組み合わせ

○大気追跡風は、海上の風の貴重なデータ源として数値予報に不可欠★
○GNSSと衛星を組み合わせた掩蔽観測も気温分布の推定に使われる

━━━━━━━━━━━━━━━━━━━━━━
